-- DRE por competência: contas a receber do Bling (data de competência), jan a out/2026 — 932 contas.
-- Entram na DRE só Revenda (B2B), Venda Direta, Venda Balcão e venda de ativo. Delivery, site e ativação já vêm das
-- plataformas, da Shopify e do Mercado Pago (ficam fora). "Sem categoria" segue a linha do mesmo cliente.
-- Pode rodar de novo: substitui o período, sem duplicar.

CREATE TABLE IF NOT EXISTS dre_receber_competencia (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  id_bling      text UNIQUE,                 -- Id da conta a receber no Bling
  mes           text NOT NULL,               -- 'AAAA-MM' da competência
  competencia   date NOT NULL,
  categoria     text NOT NULL DEFAULT '',
  nome          text NOT NULL DEFAULT '',    -- cliente
  cnpj          text,
  historico     text,
  valor         numeric(14,2) NOT NULL,
  situacao      text,                        -- pago, aberto, parcial
  id_origem     text,                        -- pedido de venda / NF no Bling
  importado_em  timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS dre_receber_competencia_mes_idx ON dre_receber_competencia (mes);

ALTER TABLE dre_receber_competencia ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS public_all ON dre_receber_competencia;
CREATE POLICY public_all ON dre_receber_competencia FOR ALL USING (true) WITH CHECK (true);

DROP TRIGGER IF EXISTS trava_mes ON dre_receber_competencia;
CREATE TRIGGER trava_mes BEFORE INSERT OR UPDATE OR DELETE ON dre_receber_competencia
  FOR EACH ROW EXECUTE FUNCTION trava_mes_dre('competencia');

DELETE FROM dre_receber_competencia WHERE competencia BETWEEN '2026-01-01' AND '2026-10-31';

ON CONFLICT (id_bling) DO UPDATE SET mes = EXCLUDED.mes, competencia = EXCLUDED.competencia, categoria = EXCLUDED.categoria,
  nome = EXCLUDED.nome, cnpj = EXCLUDED.cnpj, historico = EXCLUDED.historico, valor = EXCLUDED.valor,
  situacao = EXCLUDED.situacao, id_origem = EXCLUDED.id_origem, importado_em = now();

ON CONFLICT (id_bling) DO UPDATE SET mes = EXCLUDED.mes, competencia = EXCLUDED.competencia, categoria = EXCLUDED.categoria,
  nome = EXCLUDED.nome, cnpj = EXCLUDED.cnpj, historico = EXCLUDED.historico, valor = EXCLUDED.valor,
  situacao = EXCLUDED.situacao, id_origem = EXCLUDED.id_origem, importado_em = now();

-- Classificação por cliente das contas a receber: nova origem 'receber' na tabela de classificação
ALTER TABLE dre_mapa DROP CONSTRAINT IF EXISTS dre_mapa_origem_check;
ALTER TABLE dre_mapa ADD CONSTRAINT dre_mapa_origem_check
  CHECK (origem IN ('competencia', 'caixa_receita', 'caixa_despesa', 'receber'));

-- "MERCADO PAGO – Vendas site" sem categoria é venda do site (já vem da Shopify)
VALUES ('receber', 'Sem categoria', 'MERCADO PAGO', 'ignorar', now())
ON CONFLICT (origem, categoria, nome) DO UPDATE SET linha = EXCLUDED.linha, atualizado_em = now();

-- Conferência: um mês por linha, só o que entra na DRE pelo Bling
SELECT mes,
  sum(valor) FILTER (WHERE categoria = 'Revenda') AS revenda,
  sum(valor) FILTER (WHERE categoria = 'Venda Direta') AS direta,
  sum(valor) FILTER (WHERE categoria = 'Venda Balcão') AS balcao,
  sum(valor) FILTER (WHERE categoria = 'Sem categoria') AS sem_categoria,
  count(*) AS contas
FROM dre_receber_competencia GROUP BY mes ORDER BY mes;
